args:
Add-Type -AssemblyName System.IO.Compression.FileSystem
$target = Join-Path (Get-Location) 'Engagement-Module-Integration.docx'
if (Test-Path $target) { throw "Output already exists: $target" }
$headers = @('MODULE (EER)', 'DATA', 'CONNECTED MODULE')
$rows = @(
  [pscustomobject]@{ Cells = @('Communication', 'Announcements, HR notifications, employee messages', 'Employee Portal') },
  [pscustomobject]@{ Cells = @('Survey & Feedback', 'Survey forms, responses, HR feedback, satisfaction results', 'Employee Management, Performance Development') },
  [pscustomobject]@{ Cells = @('Recognition & Rewards', 'Recognition records, points, badges, awards, performance scores', 'Performance Development, Learning & Development') },
  [pscustomobject]@{ Cells = @('Grievances', 'Grievance records, status and updates, linked payslip/payroll and attendance data', 'Employee Management, Payroll, Attendance, Compliance & Legal Management') },
  [pscustomobject]@{ Cells = @('Social Collaborations', 'Posts, comments, reactions, groups, members, project spaces', 'Employee Management, Employee Portal') }
)
function Escape-XmlText([string]$text) { [System.Security.SecurityElement]::Escape($text) }
function Add-ZipText($archive, [string]$name, [string]$text) {
  $entry = $archive.CreateEntry($name)
  $stream = $entry.Open()
  $writer = [System.IO.StreamWriter]::new($stream, [System.Text.UTF8Encoding]::new($false))
  $writer.Write($text)
  $writer.Dispose()
}
$widths = @(3000, 5600, 5800)
$grid = ($widths | ForEach-Object { "<w:gridCol w:w=`"$_`"/>" }) -join ''
$allRows = @([pscustomobject]@{ Cells = $headers; IsHeader = $true }) + $rows
$tableRows = foreach ($rowIndex in 0..($allRows.Count - 1)) {
  $row = $allRows[$rowIndex]
  $cells = foreach ($cellIndex in 0..2) {
    $text = Escape-XmlText([string]$row.Cells[$cellIndex])
    $fill = if ($row.IsHeader) { '1F5A85' } elseif ($rowIndex % 2 -eq 0) { 'F2F6FB' } else { 'FFFFFF' }
    $color = if ($row.IsHeader) { 'FFFFFF' } else { '243447' }
    $bold = if ($row.IsHeader) { '<w:b/>' } elseif ($cellIndex -eq 0) { '<w:b/>' } else { '' }
    "<w:tc><w:tcPr><w:tcW w:w=`"$($widths[$cellIndex])`" w:type=`"dxa`"/><w:shd w:fill=`"$fill`"/><w:vAlign w:val=`"center`"/><w:tcMar><w:top w:w=`"120`" w:type=`"dxa`"/><w:start w:w=`"120`" w:type=`"dxa`"/><w:bottom w:w=`"120`" w:type=`"dxa`"/><w:end w:w=`"120`" w:type=`"dxa`"/></w:tcMar></w:tcPr><w:p><w:pPr><w:spacing w:after=`"0`"/></w:pPr><w:r><w:rPr><w:rFonts w:ascii=`"Aptos`" w:hAnsi=`"Aptos`"/><w:color w:val=`"$color`"/><w:sz w:val=`"21`"/>$bold</w:rPr><w:t xml:space=`"preserve`">$text</w:t></w:r></w:p></w:tc>"
  }
  '<w:tr>' + ($cells -join '') + '</w:tr>'
}
$title = '<w:p><w:pPr><w:spacing w:after=`"100`"/></w:pPr><w:r><w:rPr><w:rFonts w:ascii=`"Aptos Display`" w:hAnsi=`"Aptos Display`"/><w:b/><w:color w:val=`"17365D`"/><w:sz w:val=`"34`"/></w:rPr><w:t>HRMS Module Integration Overview</w:t></w:r></w:p>'
$subtitle = '<w:p><w:pPr><w:spacing w:after=`"300`"/></w:pPr><w:r><w:rPr><w:rFonts w:ascii=`"Aptos`" w:hAnsi=`"Aptos`"/><w:color w:val=`"52677D`"/><w:sz w:val=`"22`"/></w:rPr><w:t>Employee Engagement (EER)</w:t></w:r></w:p>'
$doc = '<?xml version=`"1.0`" encoding=`"UTF-8`" standalone=`"yes`"?><w:document xmlns:w=`"http://schemas.openxmlformats.org/wordprocessingml/2006/main`"><w:body>' + $title + $subtitle + '<w:tbl><w:tblPr><w:tblW w:w=`"14400`" w:type=`"dxa`"/><w:tblLayout w:type=`"fixed`"/><w:tblBorders><w:top w:val=`"single`" w:sz=`"6`" w:color=`"D6E0EA`"/><w:left w:val=`"single`" w:sz=`"6`" w:color=`"D6E0EA`"/><w:bottom w:val=`"single`" w:sz=`"6`" w:color=`"D6E0EA`"/><w:right w:val=`"single`" w:sz=`"6`" w:color=`"D6E0EA`"/><w:insideH w:val=`"single`" w:sz=`"4`" w:color=`"D6E0EA`"/><w:insideV w:val=`"single`" w:sz=`"4`" w:color=`"D6E0EA`"/></w:tblBorders></w:tblPr><w:tblGrid>' + $grid + '</w:tblGrid>' + ($tableRows -join '') + '</w:tbl><w:sectPr><w:pgSz w:w=`"15840`" w:h=`"12240`" w:orient=`"landscape`"/><w:pgMar w:top=`"720`" w:right=`"720`" w:bottom=`"720`" w:left=`"720`" w:header=`"360`" w:footer=`"360`" w:gutter=`"0`"/></w:sectPr></w:body></w:document>'
$types = '<?xml version=`"1.0`" encoding=`"UTF-8`"?><Types xmlns=`"http://schemas.openxmlformats.org/package/2006/content-types`"><Default Extension=`"rels`" ContentType=`"application/vnd.openxmlformats-package.relationships+xml`"/><Default Extension=`"xml`" ContentType=`"application/xml`"/><Override PartName=`"/word/document.xml`" ContentType=`"application/vnd.openxmlformats-officedocument.wordprocessingml.document.main+xml`"/></Types>'
$rels = '<?xml version=`"1.0`" encoding=`"UTF-8`"?><Relationships xmlns=`"http://schemas.openxmlformats.org/package/2006/relationships`"><Relationship Id=`"rId1`" Type=`"http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument`" Target=`"word/document.xml`"/></Relationships>'
$archive = [System.IO.Compression.ZipFile]::Open($target, [System.IO.Compression.ZipArchiveMode]::Create)
try {
  Add-ZipText $archive '[Content_Types].xml' $types
  Add-ZipText $archive '_rels/.rels' $rels
  Add-ZipText $archive 'word/document.xml' $doc
} finally { $archive.Dispose() }
Write-Output "Created $target"
